using GatewayService.Application;
using GatewayService.Contracts;
namespace GatewayService.Api;
public static class Endpoints
{
    private static string? User(HttpRequest r) => r.Headers["X-User-Name"].FirstOrDefault();
    public static void MapGatewayEndpoints(this WebApplication app) { app.MapGet("/manage/health", () => Results.Ok(new { status = "UP" })); app.MapGet("/api/v1/hotels", async (int? page, int? size, BookingApplication s, CancellationToken ct) => Results.Ok(await s.HotelsAsync(Math.Max(1, page ?? 1), Math.Clamp(size ?? 10, 1, 100), ct))); app.MapGet("/api/v1/loyalty", async (HttpRequest r, BookingApplication s, CancellationToken ct) => User(r) is { } u ? Results.Ok(await s.LoyaltyAsync(u, ct)) : Results.BadRequest(new ErrorResponse("X-User-Name header is required"))); app.MapGet("/api/v1/reservations", async (HttpRequest r, BookingApplication s, CancellationToken ct) => User(r) is { } u ? Results.Ok(await s.AllAsync(u, ct)) : Results.BadRequest(new ErrorResponse("X-User-Name header is required"))); app.MapGet("/api/v1/reservations/{uid:guid}", async (Guid uid, HttpRequest r, BookingApplication s, CancellationToken ct) => User(r) is { } u && await s.OneAsync(u, uid, ct) is { } x ? Results.Ok(x) : Results.NotFound(new ErrorResponse("Reservation not found"))); app.MapPost("/api/v1/reservations", async (CreateReservationRequest x, HttpRequest r, BookingApplication s, CancellationToken ct) => User(r) is { } u ? Results.Ok(await s.CreateAsync(u, x, ct)) : Results.BadRequest(new ErrorResponse("X-User-Name header is required"))); app.MapDelete("/api/v1/reservations/{uid:guid}", async (Guid uid, HttpRequest r, BookingApplication s, CancellationToken ct) => User(r) is { } u && await s.CancelAsync(u, uid, ct) ? Results.NoContent() : Results.NotFound(new ErrorResponse("Reservation not found"))); app.MapGet("/api/v1/me", async (HttpRequest r, BookingApplication s, CancellationToken ct) => User(r) is { } u ? Results.Ok(await s.MeAsync(u, ct)) : Results.BadRequest(new ErrorResponse("X-User-Name header is required"))); }
}
